function pumpBackground(){if(!ready||backgroundProcessing)return;collectBackgroundTime();if(!document.hidden&&!window.IDLE_BACKGROUND_BUSY)return;backgroundProcessing=true;try{let steps=0;while(backgroundDebt>0&&steps++<300){if(running&&G.phase==='combat'&&B.over&&B.done)break;const dt=Math.min(1/30,backgroundDebt);backgroundDebt-=dt;systems.tick(dt);hunts.tick(dt,running&&!systems.challenge());if(!running)continue;if(G.phase==='combat'&&B.on){let combatTime=dt*CFG.speed;while(combatTime>0&&B.on&&G.phase==='combat'&&!B.done){const step=Math.min(1/30,combatTime);stepBattle(step);FX.update(step);combatTime-=step}if(B.on&&!B.over&&B.t>45)next()}else if(G.phase==='plan'){FX.update(dt);backgroundWait-=dt;if(backgroundWait<=0){clearTimeout(nextTimer);safeFight();backgroundWait=2.5}}else break}}catch(error){backgroundDebt=0;showIdleError(error)}finally{backgroundProcessing=false}if(!document.hidden){if(backgroundDebt>1/1000){backgroundTimer=setTimeout(pumpBackground,0)}else{backgroundDebt=0;backgroundStamp=0;window.IDLE_BACKGROUND_BUSY=false;lastT=performance.now();if(running&&G.phase==='plan'){clearTimeout(nextTimer);nextTimer=setTimeout(()=>{if(running)safeFight()},Math.max(0,backgroundWait)*1000)}render()}}}
