function openGuidePanel(key){if(arguments[0]==='mega'){megaUI.open();return}if(['village','fishing','houses','craft'].includes(key)){closeWindows();if(key==='village')window.IDLE_VILLAGE.open();else if(key==='fishing')window.IDLE_VILLAGE.fishing();else if(key==='houses')window.IDLE_VILLAGE.deeds();else window.IDLE_OPEN_MEGA_CRAFT();return}
 if(key==='gacha')gachaUI.open();else if(key==='wiki')wikiUI.open();else if(key==='tutorial')tutorialUI.open();else if(key==='safari')safariUI.open();else if(key==='nursery')systems.open('nursery');else if(key==='tasks')systems.open('activities');else if(key==='events')eventUI.open();else if(key==='challenges')systems.open('challenges');else if(key==='history')hunts.open('history');else if(key==='party')partyUI.open();else if(key==='hunts')hunts.open();else if(key==='expedition')hunts.open('setup');else if(['capture','shiny','recovery'].includes(key))automationUI.open(key);else if(key==='center'){if(!centerUI.isOpen())centerUI.open()}else if(key==='pc')pcUI.open();else if(key==='evolution')screenUI.openEvolution();else if(key==='bag')partyUI.openBag();else if(key==='shop')shopUI.open();else if(key==='dex')fieldNotes.open('dex');else if(key==='journey')systems.open('journey');else if(key==='report')hunts.open('report');else if(key==='offline')fieldNotes.open('offline');else if(key==='trainer'){closeWindows();window.TRAINER_PROFILE?.open()}

}
